/* Render-only fractional native prediction. The authoritative room is never interpolated. */
(function(root){'use strict';const TICK=1000/60;
function horizon({value=0,remote=false,age=0,phase=0,adaptive=false,rtt=0,active=true}){if(!active)return 0;const user=Math.max(0,Math.min(1000,Number(value)||0));return user+(remote?Math.max(0,Math.min(100,age))+(adaptive?Math.max(0,Math.min(60,rtt/2)):0):Math.max(0,Math.min(TICK,phase)));}
function createSampler(){let cache=null;return function sample(room,ms,version){const frames=Math.max(0,ms)/TICK,whole=Math.floor(frames),alpha=frames-whole;const source=room.state;if(!cache||cache.room!==room||cache.source!==source||cache.version!==version||cache.whole!==whole){const low=room.extrapolate(whole*TICK+1e-7,true),a=low.gameState?.physicsState.discs.map(d=>({x:d.pos.x,y:d.pos.y}));const high=room.extrapolate((whole+1)*TICK+1e-7,true),b=high.gameState?.physicsState.discs.map(d=>({x:d.pos.x,y:d.pos.y}));cache={room,source,version,whole,state:high,a,b};}const {state,a,b}=cache;if(a&&b){const discs=state.gameState.physicsState.discs;for(let i=0;i<discs.length;i++){if(!a[i]||!b[i])continue;discs[i].pos.x=a[i].x+(b[i].x-a[i].x)*alpha;discs[i].pos.y=a[i].y+(b[i].y-a[i].y)*alpha;}}return state;};}
root.FuckballRenderTiming={TICK,horizon,createSampler};if(typeof module!=='undefined')module.exports=root.FuckballRenderTiming;
})(typeof globalThis!=='undefined'?globalThis:this);
